import * as echarts from 'echarts';

export function render() {
  const data = [
    {"hour":"9","day":"Mon","load":1},
    {"hour":"10","day":"Mon","load":5},
    {"hour":"9","day":"Tue","load":3}
  ];

  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const hours = Array.from(new Set(data.map(d => d.hour))).sort((a, b) => Number(a) - Number(b));

  const heatmapData = data.map(item => [
    hours.indexOf(item.hour),
    days.indexOf(item.day),
    item.load
  ]);

  const chart = echarts.init(null, null, {
    renderer: 'svg',
    ssr: true,
    width: 800,
    height: 400
  });

  const option = {
    tooltip: {
      position: 'top'
    },
    grid: {
      left: '10%',
      right: '10%',
      top: '10%',
      bottom: '15%'
    },
    xAxis: {
      type: 'category',
      data: hours,
      name: 'Hour',
      splitArea: {
        show: true
      }
    },
    yAxis: {
      type: 'category',
      data: days,
      name: 'Day',
      splitArea: {
        show: true
      }
    },
    visualMap: {
      min: 0,
      max: Math.max(...data.map(d => d.load)),
      calculable: true,
      orient: 'horizontal',
      left: 'center',
      bottom: '0%'
    },
    series: [{
      name: 'Load',
      type: 'heatmap',
